#include <iostream>
#include <utility>

int main() {
    // Đọc số phần tử
    int n = 0;
    if (!(std::cin >> n) || n <= 0) {
        return 0;
    }

    double a[100];
    for (int i = 0; i < n; ++i) {
        std::cin >> a[i];
    }

    // 1. Đếm dương, âm, 0
    int sd = 0, sa = 0, s0 = 0;
    for (int i = 0; i < n; ++i) {
        if (a[i] > 0.0) {
            ++sd;
        } else if (a[i] < 0.0) {
            ++sa;
        } else {
            ++s0;
        }
    }

    // 2. Tìm giá trị nhỏ nhất và chỉ số
    double min_val = a[0];
    int min_idx = 0;
    for (int i = 1; i < n; ++i) {
        if (a[i] < min_val) {
            min_val = a[i];
            min_idx = i;
        }
    }

    std::cout << "Duong: " << sd << " Am: " << sa << " Khong: " << s0 << "\n";
    std::cout << "Min: " << min_val << " tai vi tri: " << min_idx << "\n";

    // 3. Sắp xếp đổi chỗ tăng dần
    for (int i = 0; i < n - 1; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (a[i] > a[j]) {
                std::swap(a[i], a[j]);
            }
        }
    }

    std::cout << "Day sau sap xep: ";
    for (int i = 0; i < n; ++i) {
        std::cout << a[i] << (i + 1 < n ? " " : "\n");
    }

    return 0;
}

#include <iostream>

int main() {
    // Khai báo mảng 8 phần tử theo minh họa trang 66
    char s1[8] = {'H', 'E', 'L', 'L', 'O', '\0', 'A', 'B'};
    char s2[8] = {'H', 'E', 'L', '\0', 'L', 'O', '\0', 'X'};
    char s3[8] = {'\0', 'H', 'E', 'L', 'L', 'O', '\0', 'Y'};

    // In trực tiếp ra luồng: dừng lại khi gặp '\0' đầu tiên
    std::cout << "s1: [" << s1 << "]\n";
    std::cout << "s2: [" << s2 << "]\n";
    std::cout << "s3: [" << s3 << "]\n";

    // Kiểm tra kích thước mảng vật lý so với kích thước nội dung
    std::cout << "sizeof(s1): " << sizeof(s1) << " bytes\n";

    return 0;
}
